{
  "items": [
    {
      "name": "Int.gcd_least_linear",
      "module_name": "Mathlib.Data.Int.GCD",
      "kind": "theorem",
      "type": "∀ {a b : ℤ}, a ≠ 0 → IsLeast {n | 0 < n ∧ ∃ x y, ↑n = a * x + b * y} (a.gcd b)"
    },
    {
      "name": "Int.gcd_eq_gcd_ab",
      "module_name": "Mathlib.Data.Int.GCD",
      "kind": "theorem",
      "type": "∀ (x y : ℤ), ↑(x.gcd y) = x * x.gcdA y + y * x.gcdB y"
    },
    {
      "name": "Tactic.NormNum.int_gcd_helper'",
      "module_name": "Mathlib.Tactic.NormNum.GCD",
      "kind": "theorem",
      "type": "∀ {d : ℕ} {x y : ℤ} (a b : ℤ), ↑d ∣ x → ↑d ∣ y → x * a + y * b = ↑d → x.gcd y = d"
    },
    {
      "name": "Nat.gcd_eq_gcd_ab",
      "module_name": "Mathlib.Data.Int.GCD",
      "kind": "theorem",
      "type": "∀ (x y : ℕ), ↑(x.gcd y) = ↑x * x.gcdA y + ↑y * x.gcdB y"
    },
    {
      "name": "exists_gcd_eq_mul_add_mul",
      "module_name": "Mathlib.RingTheory.PrincipalIdealDomain",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [IsBezout R] [IsDomain R] [inst_3 : GCDMonoid R] (a b : R),\n  ∃ x y, gcd a b = a * x + b * y"
    }
  ]
}
